example.code:
#include <cstdint>
#include <iostream>

int main() {
    std::cout << "long " << sizeof(long) << '\n';
    std::cout << "int32_t " << sizeof(std::int32_t) << '\n';
    std::cout << "int_fast32_t " << sizeof(std::int_fast32_t) << '\n';
    std::cout << "intptr_t " << sizeof(std::intptr_t) << '\n';

    const std::uint32_t value = 0x12345678;
    std::cout << std::hex << "in memory: " << value % 0x100 << ' '
              << value / 0x100 % 0x100 << ' ' << value / 0x10000 % 0x100 << ' '
              << value / 0x1000000 << std::dec << '\n';
    return 0;
}

