#include <iomanip>
#include <iostream>

int main() {
    std::cout << std::hexfloat;
    std::cout << "101.25: " << 101.25 << '\n';
    std::cout << "0.1: " << 0.1 << '\n';
    std::cout << "0.1 + 0.2: " << 0.1 + 0.2 << '\n';
    std::cout << "0.3: " << 0.3 << '\n';
    std::cout << std::defaultfloat << std::setprecision(17);
    std::cout << 0.1 + 0.2 << ' ' << 0.3 << '\n';
    return 0;
}

